private static readonly Dictionary<string,string[]> DirectionalText=new Dictionary<string,string[]>{["ko-KR"]=new[]{"개별 점등","방향별 발광 제어","개별 점등 사용 (ON = 실제 방향별 신호 표시)","대상 렌더 메시","양보 상태 포함 (ON = 초록 단계의 양보도 표시)","두 번째 면 제어 (ON = 두 번째 ID 세트 사용)","첫 면 빨강 Layer ID","첫 면 노랑 Layer ID","첫 면 직진 초록 Layer ID","첫 면 좌회전 화살표 Layer ID","두 번째 면 빨강 Layer ID","두 번째 면 노랑 Layer ID","두 번째 면 직진 초록 Layer ID","두 번째 면 좌회전 화살표 Layer ID","적용 메시 수 / 검사 객체 수","에디터의 Multi Lights Layer ID를 입력합니다(목록 순번 아님). 빨강/노랑은 각각 TrafficLight_Red/Yellow, 직진과 화살표는 TrafficLight_Green이어야 합니다. 중복·누락·Purpose 불일치는 적용하지 않습니다. 실제 신호 주기는 변경하지 않습니다. 직진 정지·좌회전 허용이면 빨강과 화살표가 함께 켜집니다. 동일 신호 그룹이면 두 초록불도 함께 켜집니다. 미확인 접근로는 기본 점등을 유지합니다. 상태는 카메라 주변의 최근 처리 수입니다."},["en-US"]=new[]{"Individual lights","Directional light control","Independent lights (ON = actual directional signals)","Target render mesh","Include yielding (ON = yielding during a green phase)","Control second face (ON = second ID set)","First red Layer ID","First yellow Layer ID","First straight green Layer ID","First left arrow Layer ID","Second red Layer ID","Second yellow Layer ID","Second straight green Layer ID","Second left arrow Layer ID","Applied meshes / inspected objects","Enter editor Multi Lights Layer IDs, not list indices. Require TrafficLight_Red/Yellow for red/yellow and TrafficLight_Green for straight/arrow. Duplicate, missing or mismatched IDs are skipped. Timing is unchanged. Left-only permission shows red plus arrow; shared phases may light both greens. Unknown approaches keep native lights. Status counts nearby processing."},["ja-JP"]=new[]{"個別点灯","方向別発光制御","個別点灯（ON = 実際の方向別信号）","対象レンダーメッシュ","譲り状態も含む（ON = 青段階の譲りも表示）","第2面を制御（ON = 第2 IDセット）","第1面 赤 Layer ID","第1面 黄 Layer ID","第1面 直進青 Layer ID","第1面 左折矢印 Layer ID","第2面 赤 Layer ID","第2面 黄 Layer ID","第2面 直進青 Layer ID","第2面 左折矢印 Layer ID","適用メッシュ / 検査オブジェクト","一覧順ではなくエディターのLayer IDを入力。赤/黄はTrafficLight_Red/Yellow、直進/矢印はTrafficLight_Greenが必要。重複・欠落・Purpose不一致は適用しません。信号周期は変更なし。左折のみなら赤と矢印、同一段階なら両方の青が点灯。不明な進入路は標準表示。状態はカメラ周辺の処理数。"},["zh-HANS"]=new[]{"独立灯光","按方向控制发光","独立灯光（ON = 实际方向信号）","目标渲染网格","包括让行（ON = 绿灯阶段的让行）","控制第二面（ON = 第二组ID）","第一面红灯 Layer ID","第一面黄灯 Layer ID","第一面直行绿灯 Layer ID","第一面左转箭头 Layer ID","第二面红灯 Layer ID","第二面黄灯 Layer ID","第二面直行绿灯 Layer ID","第二面左转箭头 Layer ID","应用网格 / 检查对象","输入编辑器的Layer ID而非列表序号。红/黄必须为TrafficLight_Red/Yellow，直行/箭头为TrafficLight_Green。重复、缺失或Purpose不匹配时跳过。不改变信号周期。仅左转时红灯与箭头同亮，同组时两绿灯可同亮。无法识别时保留原灯光。状态为相机附近处理数量。"},["zh-HANT"]=new[]{"獨立燈光","按方向控制發光","獨立燈光（ON = 實際方向號誌）","目標渲染網格","包括讓行（ON = 綠燈階段的讓行）","控制第二面（ON = 第二組ID）","第一面紅燈 Layer ID","第一面黃燈 Layer ID","第一面直行綠燈 Layer ID","第一面左轉箭頭 Layer ID","第二面紅燈 Layer ID","第二面黃燈 Layer ID","第二面直行綠燈 Layer ID","第二面左轉箭頭 Layer ID","套用網格 / 檢查物件","輸入編輯器的Layer ID而非清單序號。紅/黃必須為TrafficLight_Red/Yellow，直行/箭頭為TrafficLight_Green。重複、缺失或Purpose不符時略過。不改變號誌週期。僅左轉時紅燈與箭頭同亮，同組時兩綠燈可同亮。無法識別時保留原燈光。狀態為相機附近處理數量。"},["es-ES"]=new[]{"Luces individuales","Control por dirección","Luces independientes (ON = señales reales por dirección)","Malla de destino","Incluir ceda el paso (ON = durante fase verde)","Controlar segunda cara (ON = segundo conjunto ID)","Rojo primero Layer ID","Amarillo primero Layer ID","Verde recto primero Layer ID","Flecha izquierda primera Layer ID","Rojo segundo Layer ID","Amarillo segundo Layer ID","Verde recto segundo Layer ID","Flecha izquierda segunda Layer ID","Mallas aplicadas / objetos inspeccionados","Use Layer ID del editor, no índices. Rojo/amarillo requieren TrafficLight_Red/Yellow; recto/flecha, TrafficLight_Green. Se omiten IDs duplicados, ausentes o incompatibles. No cambia fases. Solo izquierda muestra rojo y flecha; fases compartidas pueden encender ambos verdes. Accesos desconocidos conservan luces originales. Estado: objetos cercanos procesados."}};
private static readonly Dictionary<string,string[]> TransitionText=new Dictionary<string,string[]>{["ko-KR"]=new[]{"한국식 신호 전환 (ON = 시작 노랑 생략)","종료 노랑 표시 시간(초)","등록된 메시의 표시만 변경합니다. 시작 준비 중에는 빨강을 유지하고 실제 통행 허용 시 초록으로 전환합니다. 녹색 종료 감지 후 설정 시간 동안 노랑을 표시합니다. 좌회전 종료는 빨강+노랑입니다. 기본 1초이며 일시정지·배속을 따릅니다. TLM의 통행 허용이나 phase 길이는 변경하지 않습니다."},["en-US"]=new[]{"Korean transitions (ON = skip startup amber)","Ending amber duration (seconds)","Visuals only for registered meshes. Red remains on during preparation and turns green only when the movement is permitted. After green ends, display amber for this duration; left-turn ending shows red + amber. Default 1 second, following pause and simulation speed. Does not change TLM permissions or phases."},["ja-JP"]=new[]{"韓国式切替（ON = 開始時の黄を省略）","終了時の黄色表示時間（秒）","登録メッシュの表示のみ変更。赤から直接青へ。青の終了検出後に指定時間だけ黄を表示し、左折終了は赤＋黄。既定1秒、一時停止・倍速に追従。TLMの通行許可や周期は変更しません。"},["zh-HANS"]=new[]{"韩式切换（ON = 跳过启动黄灯）","结束黄灯时长（秒）","仅影响已注册网格。红灯直接变绿，检测到绿灯结束后显示指定时长黄灯；左转结束显示红＋黄。默认1秒，跟随暂停和模拟速度。不改变TLM通行权限或阶段。"},["zh-HANT"]=new[]{"韓式切換（ON = 跳過啟動黃燈）","結束黃燈時間（秒）","僅影響已登錄網格。紅燈直接變綠，偵測綠燈結束後顯示指定時間黃燈；左轉結束顯示紅＋黃。預設1秒，跟隨暫停與模擬速度。不變更TLM通行權限或階段。"},["es-ES"]=new[]{"Transición coreana (ON = omitir ámbar inicial)","Duración del ámbar final (segundos)","Solo aspecto de mallas registradas. Rojo pasa directamente a verde. Al finalizar verde muestra ámbar; al finalizar izquierda muestra rojo + ámbar. Predeterminado 1 segundo, respeta pausa y velocidad. No cambia permisos ni fases de TLM."}};
private static readonly Dictionary<string,string[]> MultipleText=new Dictionary<string,string[]>{["ko-KR"]=new[]{"목록에 추가할 렌더 메시 선택","선택한 메시 추가","선택한 메시 제거","적용 중인 렌더 메시 목록","메시를 선택한 뒤 추가 버튼을 누르세요. 목록의 모든 메시에 공통 Layer ID 설정을 적용합니다. 제거하려면 해당 메시를 선택하고 제거 버튼을 누르세요. 선택만 바꾸면 적용 목록은 유지됩니다."},["en-US"]=new[]{"Choose render mesh to manage","Add selected mesh","Remove selected mesh","Active render meshes","Choose a mesh and press Add. All listed meshes use the shared Layer IDs. Choose a mesh and press Remove to remove it. Changing the selection alone does not change the active list."},["ja-JP"]=new[]{"管理する描画メッシュを選択","選択メッシュを追加","選択メッシュを削除","適用中の描画メッシュ","メッシュを選択して追加します。一覧全体に共通のLayer IDを適用します。削除する場合は選択して削除を押します。選択だけでは適用一覧は変わりません。"},["zh-HANS"]=new[]{"选择要管理的渲染网格","添加所选网格","移除所选网格","已启用的渲染网格","选择网格后点击添加。列表中所有网格使用共用Layer ID。选择网格后点击移除可将其移除。仅更改选择不会改变启用列表。"},["zh-HANT"]=new[]{"選擇要管理的算繪網格","新增所選網格","移除所選網格","已啟用的算繪網格","選擇網格後點擊新增。清單內所有網格使用共用Layer ID。選擇網格後點擊移除可將其移除。僅變更選擇不會變更啟用清單。"},["es-ES"]=new[]{"Elegir malla para gestionar","Añadir malla seleccionada","Quitar malla seleccionada","Mallas activas","Elige una malla y pulsa Añadir. Todas usan los Layer ID compartidos. Selecciona una malla y pulsa Quitar para eliminarla. Cambiar solo la selección no modifica la lista activa."}};
