 private static readonly Dictionary<string,string> VehicleOnlyText=new Dictionary<string,string>{["en-US"]="Prefer a matching far-side pedestrian signal position and a combined asset. Vehicle lights follow the source; pedestrian lights follow that existing signal, whose original appearance is temporarily hidden. Without a match, use a vehicle-only copy on a safe sidewalk.",["ko-KR"]="맞은편의 짝이 맞는 보행자 신호등 위치에 겸용 에셋을 우선 표시합니다. 차량 불빛은 원본 차량 신호를, 보행 불빛은 해당 보행자 신호를 따릅니다. 기존 보행자 외형은 임시로 숨기며, 짝이 없으면 안전한 보도에 차량 전용 복제본을 배치합니다.",["ja-JP"]="対岸の対応する歩行者信号位置に兼用アセットを優先表示。車両灯は元の車両信号、歩行者灯は既存の歩行者信号に同期し、元の外観だけ一時的に非表示。一致しない場合は安全な歩道に車両用を配置。",["zh-HANS"]="优先在对面匹配的行人信号位置显示组合资产。车辆灯跟随原车辆信号，行人灯跟随该行人信号；原行人外观暂时隐藏。无匹配时在安全人行道放置车辆专用副本。",["zh-HANT"]="優先在對面匹配的行人號誌位置顯示組合資產。車輛燈跟隨原車輛號誌，行人燈跟隨該行人號誌；原行人外觀暫時隱藏。無匹配時在安全人行道放置車輛專用副本。",["es-ES"]="Prioriza una señal peatonal compatible al otro lado con un recurso combinado. Las luces de vehículos siguen el origen y las peatonales siguen esa señal, ocultando temporalmente su apariencia. Sin coincidencia, coloca una copia para vehículos en una acera segura."};
 private static readonly Dictionary<string,string[]> InsetText=new Dictionary<string,string[]> {
 ["en-US"]=new[]{"Far-side sidewalk inset (m)","Moves straight-road replicas toward the sidewalk. At a T junction, places the pole inside a detected far-side pedestrian lane, clamped to its width. Default 1 m; changes reposition replicas."},
 ["ko-KR"]=new[]{"건너편 신호등 보도 여유 거리 (m)","직진 방향 복제본을 보도 쪽으로 이동합니다. 삼거리에서는 감지한 맞은편 보행로 안쪽에 배치하며 보행로 폭을 넘지 않도록 제한합니다. 기본 1m이며 변경 시 재배치합니다."},
 ["ja-JP"]=new[]{"対岸信号の歩道側余裕（m）","直進側の複製を歩道側へ移動。T字路では検出した対岸歩行レーン内に幅を制限して配置。初期値1m、変更時に再配置。"},
